class Solution {
public:
    int nearestValidPoint(int x, int y, vector<vector<int>>& points) {
        int best = INT_MAX, ans = -1;
        for (int i = 0; i < (int)points.size(); i++) {
            int a = points[i][0], b = points[i][1];
            if (a == x || b == y) {
                int d = abs(a - x) + abs(b - y);
                if (d < best) {
                    best = d;
                    ans = i;
                }
            }
        }
        return ans;
    }
};

